// Passo 1: conferimos que veio uma lista de verdade.
function somaDaLista(numeros) {
  if (!Array.isArray(numeros)) {
    throw new Error('numeros precisa ser uma lista');
  }

  // Passo 2: o pote começa vazio.
  let soma = 0;

  // Passo 3: para cada valor da lista, jogamos no pote.
  for (const valor of numeros) {
    soma = soma + valor;
  }

  // Passo 4: devolvemos o total.
  return soma;
}

console.log(somaDaLista([1, 2, 3])); // imprime: 6
